    SELECT id INTO v_lesson_id FROM lessons WHERE topic_id=v_topic_id AND title='Some and Any';
    IF v_lesson_id IS NULL THEN INSERT INTO lessons(topic_id,teacher_id,title,description,content,skill_type,order_index,status) VALUES(v_topic_id,v_teacher_id,'Some and Any','Some is common in affirmative statements and offers; any is common in negatives and most questions.','Objective: Use some and any in affirmative, negative, and question contexts.
Content: Put some before plural countable or uncountable nouns in positive statements. Use any after not and in information questions.
Examples:
- There are some apples.
- There isn''t any bread.
- Do you have any rice?
Common errors and corrections:
- Do not use some in a normal negative statement.
- Do not forget the noun after some or any.
Guided practice: Identify whether the sentence is positive, negative, or a question.
Summary: Some and any show an unspecified quantity in different sentence types.','GRAMMAR',2,'DRAFT') RETURNING id INTO v_lesson_id; END IF;
