    SELECT id INTO v_lesson_id FROM lessons WHERE topic_id=v_topic_id AND title='Much, Many, and a Lot of';
    IF v_lesson_id IS NULL THEN INSERT INTO lessons(topic_id,teacher_id,title,description,content,skill_type,order_index,status) VALUES(v_topic_id,v_teacher_id,'Much, Many, and a Lot of','Many goes with plural countable nouns, much with uncountable nouns, and a lot of works with both.','Objective: Match quantity expressions with countable and uncountable nouns.
Content: Use many for separate items, much for substances or ideas, and a lot of in positive everyday statements.
Examples:
- How many chairs are there?
- How much water do you need?
- We have a lot of work.
Common errors and corrections:
- Do not use much with plural countable nouns.
- Do not use many with an uncountable substance.
Guided practice: Circle the noun and label it countable or uncountable before choosing the quantity word.
Summary: Many counts items, much measures an uncountable amount, and a lot of works with both.','GRAMMAR',3,'DRAFT') RETURNING id INTO v_lesson_id; END IF;
